section.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://faion.net/schemas/ramp-task-difficulty-ladder.json",
  "title": "RampLadder",
  "type": "object",
  "required": ["team", "header", "rungs", "ramps", "outcome_review"],
  "additionalProperties": false,
  "definitions": {
    "date": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"},
    "days": {"type": "number", "exclusiveMinimum": 0},
    "rung_no": {"type": "integer", "minimum": 1},
    "support": {"enum": ["full_pairing", "pair_on_pr", "review_on_pr", "review_on_design", "scheduled_check_ins"]},
    "ticket_ref": {"type": "string", "pattern": "^(https?://\\S+|[A-Z][A-Z0-9]+-[0-9]+|#[0-9]+)$"}
  },
  "properties": {
    "__faion_header__": {"type": "object"},
    "team": {"type": "string", "minLength": 2},
    "header": {
      "type": "object",
      "required": ["owner", "version", "last_reviewed", "ramp_window_days", "review_cadence", "rung_label_prefix"],
      "additionalProperties": false,
      "properties": {
        "owner": {"type": "string", "pattern": "^[a-z][a-z0-9-]*:[a-z0-9._-]+$"},
        "version": {"type": "string", "pattern": "^[0-9]+\\.[0-9]+\\.[0-9]+$"},
        "last_reviewed": {"$ref": "#/definitions/date"},
        "ramp_window_days": {"type": "integer", "minimum": 5, "maximum": 60},
        "review_cadence": {"enum": ["monthly", "quarterly"]},
        "rung_label_prefix": {"type": "string", "pattern": "^[a-z][a-z0-9/_-]*$"}
      }
    },
    "rungs": {
      "type": "array",
      "minItems": 4,
      "items": {
        "type": "object",
        "required": ["rung", "name", "ticket_pattern", "expected_duration_days", "buddy_support", "evidence", "tagged_tickets"],
        "additionalProperties": false,
        "properties": {
          "rung": {"$ref": "#/definitions/rung_no"},
          "name": {"type": "string", "minLength": 3, "not": {"pattern": "(?i)(story point|t-shirt|\\beasy\\b|\\bmedium\\b|\\bhard\\b)"}},
          "ticket_pattern": {
            "type": "object",
            "required": ["files_touched_max", "modules_crossed_max", "behind_feature_flag", "design_review_required", "examples"],
            "properties": {
              "files_touched_max": {"type": "integer", "minimum": 1},
              "modules_crossed_max": {"type": "integer", "minimum": 1},
              "behind_feature_flag": {"type": "boolean"},
              "design_review_required": {"type": "boolean"},
              "examples": {"type": "array", "minItems": 1, "items": {"type": "string", "minLength": 5, "not": {"pattern": "(?i)([0-9]+ ?(story )?points?|t-shirt|\\beasy\\b|\\bmedium\\b|\\bhard\\b)"}}}
            }
          },
          "expected_duration_days": {
            "type": "object",
            "required": ["min", "max"],
            "properties": {"min": {"$ref": "#/definitions/days"}, "max": {"$ref": "#/definitions/days"}}
          },
          "buddy_support": {"$ref": "#/definitions/support"},
          "evidence": {
            "type": "object",
            "required": ["status"],
            "properties": {
              "status": {"enum": ["validated", "unvalidated"]},
              "not_applicable": {"const": "unvalidated"},
              "merged_ref": {"$ref": "#/definitions/ticket_ref"},
              "completed_by_newcomer": {"type": "string", "minLength": 2},
              "actual_duration_days": {"$ref": "#/definitions/days"}
            },
            "if": {"properties": {"status": {"const": "validated"}}},
            "then": {"required": ["merged_ref", "completed_by_newcomer", "actual_duration_days"]},
            "else": {"required": ["not_applicable"]}
          },
          "tagged_tickets": {
            "type": "array",
            "minItems": 2,
            "items": {
              "type": "object",
              "required": ["ref", "label", "on_critical_path", "deadline_inside_ramp_window"],
              "properties": {
                "ref": {"$ref": "#/definitions/ticket_ref"},
                "label": {"type": "string", "pattern": "^[a-z][a-z0-9/_-]*[0-9]+$"},
                "on_critical_path": {"type": "boolean"},
                "deadline_inside_ramp_window": {"type": "boolean"}
              }
            }
          }
        },
        "allOf": [
          {"if": {"properties": {"rung": {"const": 1}}}, "then": {"properties": {"expected_duration_days": {"properties": {"max": {"maximum": 1}}}, "buddy_support": {"const": "full_pairing"}}}},
          {"if": {"properties": {"rung": {"maximum": 2}}}, "then": {"properties": {"tagged_tickets": {"items": {"properties": {"on_critical_path": {"const": false}, "deadline_inside_ramp_window": {"const": false}}}}}}}
        ]
      }
    },
    "ramps": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["newcomer", "start_date", "tickets_tagged_on", "progression", "time_to_first_pr_days", "rung_reached_on_last_day"],
        "additionalProperties": false,
        "properties": {
          "newcomer": {"type": "string", "minLength": 2},
          "start_date": {"$ref": "#/definitions/date"},
          "tickets_tagged_on": {"$ref": "#/definitions/date"},
          "progression": {
            "type": "array",
            "minItems": 1,
            "items": {
              "type": "object",
              "required": ["rung", "ticket", "merged_on", "actual_duration_days"],
              "properties": {
                "rung": {"$ref": "#/definitions/rung_no"},
                "ticket": {"$ref": "#/definitions/ticket_ref"},
                "merged_on": {"$ref": "#/definitions/date"},
                "actual_duration_days": {"$ref": "#/definitions/days"},
                "reclassified_to_rung": {"$ref": "#/definitions/rung_no"}
              }
            }
          },
          "time_to_first_pr_days": {"type": "number", "minimum": 0},
          "rung_reached_on_last_day": {"$ref": "#/definitions/rung_no"}
        }
      }
    },
    "outcome_review": {
      "type": "object",
      "required": ["last_run", "next_due", "ramps_reviewed", "median_time_to_first_pr_days", "per_rung", "version_bumped"],
      "additionalProperties": false,
      "properties": {
        "last_run": {"$ref": "#/definitions/date"},
        "next_due": {"$ref": "#/definitions/date"},
        "ramps_reviewed": {"type": "integer", "minimum": 0},
        "median_time_to_first_pr_days": {"type": "number", "minimum": 0},
        "per_rung": {
          "type": "array",
          "items": {
            "type": "object",
            "required": ["rung", "median_actual_days", "within_band", "consecutive_out_of_band_cycles", "action"],
            "properties": {
              "rung": {"$ref": "#/definitions/rung_no"},
              "median_actual_days": {"type": ["number", "null"]},
              "within_band": {"type": "boolean"},
              "consecutive_out_of_band_cycles": {"type": "integer", "minimum": 0},
              "action": {"enum": ["none", "rebanded", "pattern_rewritten"]}
            },
            "if": {"properties": {"within_band": {"const": false}}},
            "then": {"properties": {"action": {"enum": ["rebanded", "pattern_rewritten"]}}}
          }
        },
        "version_bumped": {"type": "boolean"}
      }
    }
  }
}

