{
  "team": "payments-platform",
  "header": {
    "owner": "tech-lead:alice.m",
    "version": "1.2.0",
    "last_reviewed": "2026-06-30",
    "ramp_window_days": 10,
    "review_cadence": "quarterly",
    "rung_label_prefix": "ramp/rung-"
  },
  "rungs": [
    {
      "rung": 1,
      "name": "read-only change that ships",
      "ticket_pattern": {"files_touched_max": 1, "modules_crossed_max": 1, "behind_feature_flag": false, "design_review_required": false, "examples": ["docs typo fix in README", "dependency patch bump", "add a log line"]},
      "expected_duration_days": {"min": 0.25, "max": 1},
      "buddy_support": "full_pairing",
      "evidence": {"status": "validated", "merged_ref": "https://github.com/acme/payments/pull/812", "completed_by_newcomer": "dmytro.k", "actual_duration_days": 0.4},
      "tagged_tickets": [
        {"ref": "PAY-2210", "label": "ramp/rung-1", "on_critical_path": false, "deadline_inside_ramp_window": false},
        {"ref": "PAY-2214", "label": "ramp/rung-1", "on_critical_path": false, "deadline_inside_ramp_window": false}
      ]
    },
    {
