      "expected_duration_days": {"min": 3, "max": 5},
      "buddy_support": "review_on_design",
      "evidence": {"status": "validated", "merged_ref": "https://github.com/acme/payments/pull/840", "completed_by_newcomer": "dmytro.k", "actual_duration_days": 4},
      "tagged_tickets": [
        {"ref": "PAY-2240", "label": "ramp/rung-4", "on_critical_path": false, "deadline_inside_ramp_window": false},
        {"ref": "PAY-2241", "label": "ramp/rung-4", "on_critical_path": false, "deadline_inside_ramp_window": true}
      ]
    },
    {
      "rung": 5,
