      "ticket_pattern": {"files_touched_max": 25, "modules_crossed_max": 3, "behind_feature_flag": true, "design_review_required": true, "examples": ["partial-refund flow from API to ledger entry behind a flag"]},
      "expected_duration_days": {"min": 5, "max": 10},
      "buddy_support": "scheduled_check_ins",
      "evidence": {"status": "unvalidated", "not_applicable": "unvalidated"},
      "tagged_tickets": [
        {"ref": "PAY-2250", "label": "ramp/rung-5", "on_critical_path": false, "deadline_inside_ramp_window": false},
        {"ref": "PAY-2252", "label": "ramp/rung-5", "on_critical_path": false, "deadline_inside_ramp_window": false}
      ]
    }
  ],
